// #95ffe2 API נתוני מגמות ודשבורד — аккаунт nogoal (нет цели). Только чтение.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import { openAs, saveSession, getTrends, getGoal, ok, todayIn, expectInvariants, rangeCases } from './_trends';

test.describe.configure({ mode: 'serial' });
// Встроенный Chromium Playwright на этой машине не запускается (context.md) — установленный Google Chrome.
test.use({ channel: 'chrome' });

test.describe('trends API — nogoal', () => {
  let ctx: BrowserContext;
  let page: Page;
  let today: string;

  test.beforeAll(async ({ browser }) => {
    ({ ctx, page } = await openAs(browser, 'nogoal'));
    today = await todayIn(page);
  });
  test.afterAll(async () => {
    if (ctx) await saveSession(ctx, page, 'nogoal');
  });

  test('без цели: на всех диапазонах notEnoughReason=no_goal, метрик и home нет #95ffe2 @desktop @prod-safe', async () => {
    // AC6 (нет метрик без цели), AC7 (индикатор «недостаточно данных» — причина no_goal).
    const { goal } = await getGoal(page);
    expect(goal ?? null, 'предусловие: у nogoal нет цели').toBeNull();
    for (const c of rangeCases(today)) {
      const t = ok(await getTrends(page, c.range), c.name);
      expect(t.range, `${c.name}: range`).toMatchObject({ from: c.from, to: c.to, days: c.days });
      expectInvariants(t, `nogoal/${c.name}`);
      expect(t.enoughData, `${c.name}: enoughData`).toBe(false);
      expect(t.notEnoughReason, `${c.name}: причина`).toBe('no_goal');
      expect(t.metrics, `${c.name}: metrics`).toEqual([]);
      expect(t.home, `${c.name}: home`).toEqual([]);
    }
  });
});
